sp_widget.script:
(function() { data.applicationId = $sp.getParameter("app_id") || ""; data.canSubmit = false; data.submitted = false;
  try { if (!data.applicationId) return; var gr = new GlideRecord("x_1433041_identi_0_application"); if (!gr.get(data.applicationId)) return;
    var completion = parseInt(gr.getValue("completion_percent") || "0", 10);
    data.canSubmit = completion >= 80 && gr.getValue("questionnaire_status") !== "submitted" && gr.getValue("questionnaire_status") !== "completed";
    data.status = gr.getDisplayValue("questionnaire_status"); data.completion = completion;
    if (input && input.action === "submit" && data.canSubmit) { gr.setValue("questionnaire_status", "submitted"); gr.setValue("submitted_date", new GlideDateTime().getValue()); gr.update(); data.submitted = true; data.canSubmit = false; data.status = "Submitted"; }
  } catch (e) { gs.error("IBAR Submit Action widget error: " + e.message); }
})();
